/**
 * Generated files regenerate instead of resolving, through the tick on real git: a base update whose
 * conflicts are all files the team's `regenerate` mapping covers is completed by norn (base side, the
 * mapped command, a merge commit with `Norn-Regenerated`) with no agent session, and the story goes on
 * to its test step as after any merge. A failing command goes to resolve with its output in the brief.
 */
import { afterAll, beforeAll, describe, expect, setDefaultTimeout, test } from "bun:test";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import type { BriefJson } from "@norn/core";
import { type Receipt, SPECS_DIR } from "@norn/schema";
import { listReceipts, workflowsDir } from "@norn/store";
import { createHarness, type Harness, installBundledSkills, issue, runChecked, sh } from "../../../../test/support/harness.ts";
import { runStateOf } from "../../../../test/support/run-state.ts";

setDefaultTimeout(30_000);

const HELD = `name: held
start: ready
steps:
  ready:
    type: gate
    outcomes:
      approve: $done
      reject: $stuck
      stale: { to: update, counter: stale_loop }
  update:
    type: git
    action: update
    outcomes: { done: test, conflict: { to: resolve, counter: base_conflict_loop } }
  test:
    type: check
    run: "true"
    timeout: 1m
    outcomes: { pass: ready, fail: $stuck }
  resolve:
    type: agent
    skill: norn-merge
    inputs: [spec, handoff]
    outcomes: { done: { to: update, means: "base merged into the story branch, conflicts resolved and committed" } }
counters: { base_conflict_loop: { max: 2 }, stale_loop: { max: 3 } }
`;

/** a fake emit: gen/out.txt is "generated" plus src.txt */
const EMIT = "mkdir -p gen && { echo generated; cat src.txt; } > gen/out.txt";

function landOnBase(h: Harness, files: Record<string, string>, message: string): string {
  const dir = join(h.dir, `base-${Math.random().toString(36).slice(2)}`);
  sh(h.dir, ["clone", "-q", "-b", "main", h.remoteDir, dir]);
  sh(dir, ["config", "user.email", "s@example.com"]);
  sh(dir, ["config", "user.name", "Sibling"]);
  for (const [file, text] of Object.entries(files)) {
    mkdirSync(dirname(join(dir, file)), { recursive: true });
    writeFileSync(join(dir, file), text);
  }
  sh(dir, ["add", "-A"]);
  sh(dir, ["commit", "-q", "-m", message]);
  sh(dir, ["push", "-q", "origin", "main"]);
  return sh(dir, ["rev-parse", "HEAD"]);
}

describe("regenerate at a base update", () => {
  let h: Harness;
  const wt = () => h.worktree("gh-7-add-login-form");
  const runs = () => runStateOf(join(wt(), `${SPECS_DIR}/gh-7-add-login-form`));
  const receipts = (): Receipt[] => listReceipts(runs()).receipts.map((r) => r.receipt);
  const until = async (pred: () => boolean, label: string, max = 20) => {
    for (let i = 0; i < max && !pred(); i++) {
      h.clock.advance(10_000);
      await h.tick();
    }
    if (!pred()) throw new Error(`${label} not reached: ${JSON.stringify(h.state(runs()))}`);
  };
  const atReady = () => h.state(runs())?.step === "ready" && h.state(runs())?.status === "parked";
  /** the story regenerates gen/out.txt on its side, then the base moves src.txt and regenerates it too */
  const clash = (n: number) => {
    writeFileSync(join(wt(), "gen", "out.txt"), `generated\none\nstory ${n}\n`);
    h.git(["add", "-A"], wt());
    h.git(["commit", "-q", "-m", `story regenerates ${n}`, "--trailer", "Norn-Tick: 01JBQ6ZK3E8Y4V5W6X7Y8Z9ABC"], wt());
    return landOnBase(h, { "src.txt": `base ${n}\n`, "gen/out.txt": `generated\nbase ${n} by hand\n` }, `base moves src ${n}`);
  };

  beforeAll(async () => {
    h = await createHarness();
    h.config(`provider: gh\nworkflow: held\nmode: auto\nregenerate:\n  - { paths: ["gen/**"], run: ${JSON.stringify(EMIT)} }\n`);
    h.recordVersion();
    h.write(join(workflowsDir(h.root), "held.yaml"), HELD);
    installBundledSkills(h.root);
    writeFileSync(join(h.root, "src.txt"), "one\n");
    mkdirSync(join(h.root, "gen"), { recursive: true });
    writeFileSync(join(h.root, "gen", "out.txt"), "generated\none\n");
    h.git(["add", "-A"]);
    h.git(["commit", "-q", "-m", "norn init"]);
    h.git(["push", "-q", "origin", "main"]);
    h.remote.issues = [issue(7, "Add login form")];
    await h.tick();
    h.clock.advance(10_000);
    await h.tick("--sync");
    await until(atReady, "ready");
  });
  afterAll(() => h.cleanup());

  test("every conflict mapped → merged with Norn-Regenerated by norn, no agent, then the test step", async () => {
    const launches = h.runner.launches.length;
    const base = clash(1);
    h.clock.advance(10_000);
    await h.tick("--sync");
    await until(() => receipts().some((r) => r.kind === "check" && r.step === "test") && atReady(), "test then ready");
    const update = receipts().filter((r) => r.kind === "classify" && r.step === "update").at(-1) as Extract<Receipt, { kind: "classify" }>;
    expect(update).toMatchObject({ outcome: "done", route: "test", base: { sha: base, merged: true, regenerated: ["gen/out.txt"] } });
    expect(update.detail).toContain("regenerated gen/out.txt");
    expect(h.runner.launches.length).toBe(launches);
    const merge = update.base?.head as string;
    expect(sh(wt(), ["log", "-1", "--format=%P", merge]).split(" ")[1]).toBe(base);
    expect(sh(wt(), ["log", "-1", "--format=%(trailers:key=Norn-Regenerated,valueonly)", merge])).toBe("gen/out.txt");
    // what the command makes from the merged sources, never either side's copy
    expect(sh(wt(), ["show", `${merge}:gen/out.txt`])).toBe("generated\nbase 1");
    expect(sh(wt(), ["status", "--porcelain"])).toBe("");
  });

  test("a failing command → resolve, with what it printed in the resolver's brief", async () => {
    h.config(`provider: gh\nworkflow: held\nmode: auto\nregenerate:\n  - { paths: ["gen/**"], run: "echo emit broke >&2; exit 4" }\n`);
    clash(2);
    h.clock.advance(10_000);
    await h.tick("--sync");
    await until(() => h.state(runs())?.step === "resolve", "resolve");
    const update = receipts().filter((r) => r.kind === "classify" && r.step === "update").at(-1) as Extract<Receipt, { kind: "classify" }>;
    expect(update).toMatchObject({ outcome: "conflict", base: { conflicts: ["gen/out.txt"], regenerate: { output: "$ echo emit broke >&2; exit 4\nemit broke\n(exit 4)" } } });
    expect(sh(wt(), ["status", "--porcelain"])).toBe("");
    const r = await runChecked(["brief", "--json"], { ...h.deps, cwd: wt() });
    const { brief, markdown } = r.value as { brief: BriefJson; markdown: string };
    expect(brief.rework?.base?.regenerate?.output).toContain("emit broke");
    expect(markdown).toContain("ran the team's regenerate commands; that did not finish the merge");
  });
});
